using System.Collections.Immutable;
using RolltheSpire2.Core.Identity;

namespace RolltheSpire2.Core.PredictorRuntime;

internal sealed record PredictorOperationActInformation(int Act, ModelKey ActKey, ModelKey Ancient,
    ImmutableArray<ModelKey> RemainingBosses, bool IsNextAct)
{
    // These identities were generated by the real run before this capture.
    // Reusing them does not create another random draw or a new forecast line.
    internal string Provenance => "ObservedGeneratedRunIdentity";
}

internal static class PredictorOperationInformation
{
    internal static ImmutableArray<PredictorOperationActInformation> CurrentAndNextAct(PredictorOperationSnapshot snapshot)
    {
        var current = snapshot.State.Position.Act;
        return snapshot.State.Acts.Where(a => a.Act == current || a.Act == current + 1)
            .Select(a => new PredictorOperationActInformation(a.Act, a.Key, a.Ancient,
                a.Bosses.Skip(a.BossCursor).ToImmutableArray(), a.Act == current + 1)).ToImmutableArray();
    }
}
